/**
 * Hand-written API docs must not name options the type does not have (R22 TASK 57).
 *
 * `docs/api/compiler.md` is prose with a `transformModule({...})` example. The
 * type lives in `docs/api/snapshots/compiler.main.api.md`, generated by
 * `api:check`. Nothing connected the two, so the doc could document an option
 * that was renamed or removed and the only way to find out was to copy the
 * example and watch it fail to typecheck.
 *
 * This asserts the weaker, checkable half: every option key the example passes
 * exists in the interface. It does not check that the prose is still true — that
 * is not mechanically decidable — and it does not check the reverse (every field
 * is documented), because the type has fields the doc deliberately leaves to the
 * snapshot.
 */
import fs from 'node:fs'
import path from 'node:path'

import { describe, expect, it } from 'vitest'

const root = path.resolve(import.meta.dirname, '../../..')

/** Field names of an interface in an API-extractor snapshot. */
function interfaceFields(snapshot: string, name: string): string[] {
  const block = snapshot.match(
    new RegExp(`interface ${name}\\s*\\{([\\s\\S]*?)\\n\\}`),
  )
  if (!block?.[1]) return []
  return [...block[1].matchAll(/^\s*(\w+)\??:/gm)].map(match => match[1]!)
}

/** Option keys in the first `transformModule({ ... })` example of a doc. */
function exampleKeys(markdown: string, call: string): string[] {
  const block = markdown.match(
    new RegExp(`${call}\\(\\{([\\s\\S]*?)\\n\\}\\)`),
  )?.[1]
  if (!block) return []
  return [...block.matchAll(/^\s*(\w+):/gm)].map(match => match[1]!)
}

describe('API docs against the type snapshot', () => {
  const snapshot = fs.readFileSync(
    path.join(root, 'docs/api/snapshots/compiler.main.api.md'),
    'utf8',
  )
  const doc = fs.readFileSync(path.join(root, 'docs/api/compiler.md'), 'utf8')

  it('finds the interface and the example at all', () => {
    // Without this, a renamed interface or a reformatted example would make the
    // assertions below pass vacuously on empty arrays.
    expect(
      interfaceFields(snapshot, 'TransformModuleOptions').length,
      'TransformModuleOptions was not found in the API snapshot',
    ).toBeGreaterThan(0)
    expect(
      exampleKeys(doc, 'transformModule').length,
      'no transformModule({...}) example was found in the doc',
    ).toBeGreaterThan(0)
  })

  it('documents only options the type declares', () => {
    const fields = interfaceFields(snapshot, 'TransformModuleOptions')
    const used = exampleKeys(doc, 'transformModule')
    const unknown = used.filter(key => !fields.includes(key))
    expect(
      unknown,
      `docs/api/compiler.md passes options the type does not declare: ${unknown.join(', ')}`,
    ).toEqual([])
  })

  it('documents the fields that change the output shape', () => {
    // `autoHydrate` and `hmr` decide whether the hydration and HMR plans exist,
    // and both are absent from the example because they default off. A doc that
    // never names them leaves a reader unable to find out why a plan is null.
    expect(doc).toContain('hydrationPlan')
    expect(doc).toContain('hmrPlan')
  })
})
